BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY; SELECT 'MONEY_DEV_PREFLIGHT_BEGIN'; SELECT json_build_object('database',current_database(),'readOnly',current_setting('transaction_read_only'),'history',(SELECT string_agg(version||'='||checksum,',' ORDER BY installed_rank) FROM public.flyway_schema_history WHERE version IS NOT NULL),'scriptsDigest',(SELECT md5(string_agg(script,'|' ORDER BY installed_rank)) FROM public.flyway_schema_history WHERE version IS NOT NULL),'failed',(SELECT count(*) FROM public.flyway_schema_history WHERE NOT success),'presetConflicts',(SELECT count(*) FROM (SELECT t.user_id,p->>'id' FROM public.money_work_templates t CROSS JOIN LATERAL jsonb_array_elements(t.data->'presets') p GROUP BY t.user_id,p->>'id' HAVING count(DISTINCT p)>1) q),'workplaceTable',to_regclass('public.money_workplaces')); SELECT json_build_object('table','money_coupang_work_records','count',count(*),'digest',md5(coalesce(string_agg((to_jsonb(t)-'workplace_id')::text,'' ORDER BY id),''))) FROM public.money_coupang_work_records t WHERE id NOT IN ('ce802aca-ab9f-4bbd-abcc-0283b1aed156'::uuid,'ce20ad04-5994-4db8-8e93-6984558c48dd'::uuid,'61f973d7-0c69-4713-9af1-df4cdc77ef87'::uuid); SELECT json_build_object('table','money_work_templates','count',count(*),'digest',md5(coalesce(string_agg((to_jsonb(t)-'workplace_id')::text,'' ORDER BY id),''))) FROM public.money_work_templates t WHERE id NOT IN ('e0c3a555-8872-404e-8b6c-3eecfb5b616a'::uuid,'89731b20-282b-46eb-b542-775aee501bfc'::uuid); SELECT json_build_object('table','money_work_earnings_weeks','count',count(*),'digest',md5(coalesce(string_agg((to_jsonb(t)-'workplace_id')::text,'' ORDER BY id),''))) FROM public.money_work_earnings_weeks t WHERE id NOT IN ('6a9d8735-8cbe-4192-85df-77118270d2b2'::uuid,'01d11357-4f12-41b8-bad8-a1fc120c60cf'::uuid); SELECT json_build_object('table','money_work_payments','count',count(*),'digest',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) FROM public.money_work_payments t; SELECT json_build_object('table','money_transactions','count',count(*),'digest',md5(coalesce(string_agg(to_jsonb(t)::text,'' ORDER BY id),''))) FROM public.money_transactions t; SELECT 'MONEY_DEV_PREFLIGHT_END'; ROLLBACK;
BEGIN READ ONLY; SELECT 'MONEY_QA_STATE_BEGIN'; SELECT json_build_object('kind','record','id',id,'removed',data->>'removed','status',data->>'status') FROM public.money_coupang_work_records WHERE id IN ('ce802aca-ab9f-4bbd-abcc-0283b1aed156'::uuid,'ce20ad04-5994-4db8-8e93-6984558c48dd'::uuid,'61f973d7-0c69-4713-9af1-df4cdc77ef87'::uuid); SELECT json_build_object('kind','template','id',id,'active',data->>'active') FROM public.money_work_templates WHERE id IN ('e0c3a555-8872-404e-8b6c-3eecfb5b616a'::uuid,'89731b20-282b-46eb-b542-775aee501bfc'::uuid); SELECT json_build_object('kind','place','id',id,'active',data->>'active','activePresets',(SELECT count(*) FROM jsonb_array_elements(data->'presets') p WHERE p->>'active'='true')) FROM public.money_workplaces WHERE id IN ('da2779a2-9079-4e4d-8802-ba87ad900083'::uuid,'8776e564-4ad9-48a5-bfdc-880acebffaf8'::uuid); SELECT json_build_object('kind','week','id',id,'special',data->>'specialWorkAllowance','holiday',data->>'weeklyHolidayAllowance') FROM public.money_work_earnings_weeks WHERE id IN ('6a9d8735-8cbe-4192-85df-77118270d2b2'::uuid,'01d11357-4f12-41b8-bad8-a1fc120c60cf'::uuid); SELECT 'MONEY_QA_STATE_END'; ROLLBACK;